-- Generated by Supabase CLI 2.122.0; candidate only, never applied to a hosted project.
-- Trusted Edge derives the next state using the SAME domain modules as the app.
-- Authenticated browsers cannot call the privileged commit boundary directly.
do $$ begin
  if current_setting('mora.environment',true) is distinct from 'mora-isolated-dev' then
    raise exception 'Dedicated disposable Mora development database required';
  end if;
end $$;

create schema mora_rc;
revoke all on schema mora_rc from public, anon;
grant usage on schema mora_rc to authenticated, service_role;

create table mora_rc.businesses (
  id uuid primary key,
  revision bigint not null default 0 check(revision>=0),
  snapshot jsonb not null check(jsonb_typeof(snapshot)='object'),
  updated_at timestamptz not null default now()
);
create table mora_rc.memberships (
  business_id uuid not null references mora_rc.businesses(id),
  user_id uuid not null references auth.users(id),
  revoked_at timestamptz,
  primary key(business_id,user_id)
);
create table mora_rc.devices (
  business_id uuid not null,
  id uuid not null,
  user_id uuid not null,
  revoked_at timestamptz,
  primary key(business_id,id),
  foreign key(business_id,user_id) references mora_rc.memberships(business_id,user_id)
);
create table mora_rc.commands (
  business_id uuid not null references mora_rc.businesses(id),
  id text not null check(id ~ '^[a-zA-Z0-9_-]{1,80}$'),
  device_id uuid not null,
  user_id uuid not null,
  request jsonb not null check(jsonb_typeof(request)='object'),
  digest text not null check(digest ~ '^[0-9a-f]{64}$'),
  response jsonb not null check(response->>'status'='confirmed'),
  revision bigint not null check(revision>0),
  confirmed_at timestamptz not null default now(),
  primary key(business_id,id),
  unique(business_id,revision),
  foreign key(business_id,device_id) references mora_rc.devices(business_id,id),
  foreign key(business_id,user_id) references mora_rc.memberships(business_id,user_id)
);
-- Read projection of the authoritative snapshot. No caller writes related facts separately.
-- JSON bodies retain exact rational costs and legacy identities without lossy SQL casts.
create table mora_rc.facts (
  business_id uuid not null references mora_rc.businesses(id),
  entity text not null check(entity in ('products','sales','lots','receipts','purchaseOrders','supplierLists','supplierAliases','priceReviews','ledger','referenceLog','checks','operations','stockOpenings','stockReviews','stockResolutions','debts','debtPayments','saleCorrections','inventoryAdjustments','receiptPayments','debtAdjustments','monthlyGoals')),
  position integer not null check(position>=0),
  body jsonb not null check(jsonb_typeof(body)='object'),
  primary key(business_id,entity,position)
);
create index membership_user_lookup on mora_rc.memberships(user_id,business_id) where revoked_at is null;

alter table mora_rc.businesses enable row level security;
alter table mora_rc.memberships enable row level security;
alter table mora_rc.devices enable row level security;
alter table mora_rc.commands enable row level security;
alter table mora_rc.facts enable row level security;
create policy own_membership on mora_rc.memberships for select to authenticated using(user_id=(select auth.uid()) and revoked_at is null);
create policy visible_business on mora_rc.businesses for select to authenticated using(exists(select 1 from mora_rc.memberships m where m.business_id=id and m.user_id=(select auth.uid()) and m.revoked_at is null));
create policy own_devices on mora_rc.devices for select to authenticated using(user_id=(select auth.uid()) and revoked_at is null and exists(select 1 from mora_rc.memberships m where m.business_id=devices.business_id and m.user_id=(select auth.uid()) and m.revoked_at is null));
create policy visible_commands on mora_rc.commands for select to authenticated using(exists(select 1 from mora_rc.memberships m where m.business_id=commands.business_id and m.user_id=(select auth.uid()) and m.revoked_at is null));
create policy visible_facts on mora_rc.facts for select to authenticated using(exists(select 1 from mora_rc.memberships m where m.business_id=facts.business_id and m.user_id=(select auth.uid()) and m.revoked_at is null));
revoke all on all tables in schema mora_rc from public,anon,authenticated;
grant select on all tables in schema mora_rc to authenticated;
grant select,insert,update on mora_rc.businesses to service_role;
grant select,insert,delete on mora_rc.facts to service_role;
grant select,insert on mora_rc.commands to service_role;
grant select on mora_rc.memberships,mora_rc.devices to service_role;
-- PostgreSQL row-locking reads require UPDATE on at least one column.
-- This remains server-only; authenticated/anon have no revocation or write grant.
grant update(revoked_at) on mora_rc.memberships,mora_rc.devices to service_role;
-- Provisioning/revocation is an operator action, not an app endpoint.

create function mora_rc.assert_actor(p_business uuid,p_device uuid,p_actor uuid) returns void
language plpgsql security invoker set search_path='' as $$
begin
  if p_actor is null or not exists(select 1 from mora_rc.memberships m where m.business_id=p_business and m.user_id=p_actor and m.revoked_at is null for share)
     or not exists(select 1 from mora_rc.devices d where d.business_id=p_business and d.id=p_device and d.user_id=p_actor and d.revoked_at is null for share) then
    raise exception using errcode='42501',message='Business membership or device not authorized';
  end if;
end $$;
revoke all on function mora_rc.assert_actor(uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function mora_rc.assert_actor(uuid,uuid,uuid) to service_role;

create function public.mora_rc_read(p_business uuid,p_device uuid,p_actor uuid) returns jsonb
language plpgsql security invoker set search_path='' as $$
declare b mora_rc.businesses;
begin
  perform mora_rc.assert_actor(p_business,p_device,p_actor);
  select * into strict b from mora_rc.businesses where id=p_business;
  return jsonb_build_object('snapshot',b.snapshot,'revision',b.revision);
end $$;
revoke all on function public.mora_rc_read(uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function public.mora_rc_read(uuid,uuid,uuid) to service_role;

create function public.mora_rc_lookup(p_business uuid,p_device uuid,p_actor uuid,p_request jsonb) returns jsonb
language plpgsql security invoker set search_path='' as $$
declare c mora_rc.commands;
begin
  perform mora_rc.assert_actor(p_business,p_device,p_actor);
  if p_request->>'businessId' is distinct from p_business::text or p_request->>'deviceId' is distinct from p_device::text then
    raise exception using errcode='42501',message='Command identity mismatch';
  end if;
  select * into c from mora_rc.commands where business_id=p_business and id=p_request->>'id';
  if not found then return null;end if;
  if c.user_id<>p_actor or c.device_id<>p_device or c.request<>p_request then
    raise exception using errcode='22023',message='Command ID already has different content or identity';
  end if;
  return c.response;
end $$;
revoke all on function public.mora_rc_lookup(uuid,uuid,uuid,jsonb) from public,anon,authenticated;
grant execute on function public.mora_rc_lookup(uuid,uuid,uuid,jsonb) to service_role;

create function public.mora_rc_commit(p_business uuid,p_device uuid,p_actor uuid,p_request jsonb,p_digest text,p_next jsonb,p_response jsonb) returns jsonb
language plpgsql security invoker set search_path='' as $$
declare current_revision bigint;prior jsonb;entry record;item record;
begin
  perform mora_rc.assert_actor(p_business,p_device,p_actor);
  -- Serialize all facts of one business; different businesses use different rows.
  select revision into strict current_revision from mora_rc.businesses where id=p_business for update;
  prior:=public.mora_rc_lookup(p_business,p_device,p_actor,p_request);
  if prior is not null then return prior;end if;
  if (p_request->>'expectedRevision')::bigint<>current_revision then
    raise exception using errcode='40001',message='Business changed; preserve physical evidence for review';
  end if;
  if p_response->>'status' is distinct from 'confirmed' or (p_response->>'revision')::bigint<>current_revision+1
     or p_response->>'id' is distinct from p_request->>'id' or p_response->'payload' is distinct from p_request->'payload'
     or p_response->>'businessId' is distinct from p_business::text or p_response->>'deviceId' is distinct from p_device::text
     or jsonb_typeof(p_next) is distinct from 'object' then
    raise exception using errcode='22023',message='Invalid server confirmation';
  end if;
  update mora_rc.businesses set revision=current_revision+1,snapshot=p_next,updated_at=now() where id=p_business;
  insert into mora_rc.commands(business_id,id,device_id,user_id,request,digest,response,revision)
    values(p_business,p_request->>'id',p_device,p_actor,p_request,p_digest,p_response,current_revision+1);
  delete from mora_rc.facts where business_id=p_business;
  for entry in select key,value from jsonb_each(p_next) where key in ('products','sales','lots','receipts','purchaseOrders','supplierLists','supplierAliases','priceReviews','ledger','referenceLog','checks','operations','stockOpenings','stockReviews','stockResolutions','debts','debtPayments','saleCorrections','inventoryAdjustments','receiptPayments','debtAdjustments','monthlyGoals') loop
    for item in select value,ordinality from jsonb_array_elements(entry.value) with ordinality loop
      insert into mora_rc.facts values(p_business,entry.key,item.ordinality-1,item.value);
    end loop;
  end loop;
  return p_response;
end $$;
revoke all on function public.mora_rc_commit(uuid,uuid,uuid,jsonb,text,jsonb,jsonb) from public,anon,authenticated;
grant execute on function public.mora_rc_commit(uuid,uuid,uuid,jsonb,text,jsonb,jsonb) to service_role;
